/**
 * Returns whether an inline JSON Schema object satisfies
 * {@link CANVAS_SCHEMA_MAX_PROPERTIES} and {@link CANVAS_SCHEMA_MAX_DEPTH}.
 * Hosts MUST reject (or represent via a `*Ref` field instead of inlining)
 * any schema for which this returns `false`.
 *
 * Only walks `properties`-shaped nesting (recursing into any property value
 * that itself looks like a nested object schema, i.e. carries its own
 * `properties`). A schema that manages to exceed the property or depth bound
 * through some other JSON Schema construct (e.g. `$ref`, `items`,
 * `oneOf`/`anyOf`) is out of scope for this helper and MUST still be
 * rejected by a conformant host.
 *
 * @category Canvas Limits
 */
export function isCanvasSchemaWithinLimits(
	schema: { readonly properties?: Record<string, unknown> },
	depth = 1,
): boolean {
	const props = schema.properties;
	if (!props) {
		return true;
	}
	if (Object.keys(props).length > CANVAS_SCHEMA_MAX_PROPERTIES) {
		return false;
	}
	for (const value of Object.values(props)) {
		if (!isRecord(value)) {
			continue;
		}
		const nestedProperties = value.properties;
		if (!isRecord(nestedProperties)) {
			continue;
		}
		if (depth >= CANVAS_SCHEMA_MAX_DEPTH) {
			return false;
		}
		if (!isCanvasSchemaWithinLimits({ properties: nestedProperties }, depth + 1)) {
			return false;
		}
	}
	return true;
}

/** Type predicate narrowing an arbitrary schema-property value to a plain object, so `.properties` can be read without a type assertion. */
function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null;
}

